local core=AimohPMXFullVoiceCore.create()
-- Route the scenes declared by this voice pack and keep their own variants.
for _,rule in ipairs(core.rules) do
    for level,cue in ipairs(rule.cues) do
        local pool={}
        for _,variant in ipairs({"A","B","C"}) do
            local id=cue:sub(1,-2)..variant
            if clips[id] then pool[#pool+1]=id end
        end
        if #pool>0 then
            core.pools[cue]=pool
        else
            rule.cues[level]=false
            core.pools[cue]=nil
        end
    end
end
local current=core.current
function core.current(state,now,settings)
    local active=current(state,now,settings)
    if active or state.maxPriority>0 then return active end
    return core.propose(state,{cue="Idle_A",priority=0,key="Idle",kind="idle"},now,settings)
end
for cue,clip in pairs(clips) do clip.sound="AimohPMXSoppo_"..cue end
AimohPMXVoiceIdentity.registerVoice("pmx-40dbcd572c1fb3f8","Soppo")
local native=AimohPMXNativeVoice.create({
    prefix="AimohPMXSoppoSilent",suffixes=AimohPMXSilentVoiceData.suffixes,
},"AimohPMXSoppoOriginalVoicePrefix")
AimohPMXVoiceEngine.install({
    id="Soppo",facade={},core=core,native=native,
    resolve=function(_,cue) return clips[cue] end,
    captionTag="aimohpmxsoppovoice",logTag="[AimohPMXSoppoVoice]",
    cues={shout="Shout_A",sneakShout="SneakShout_A"},killCue="Kill_A",
})
